        /**
         * ScoreBreakdown
         * @description Per-stage detail behind a chunk's single `score`.
         *
         *     `score` is the RRF fusion score, and every stage after fusion only reorders —
         *     it never rewrites that number. So the score alone cannot say whether a chunk
         *     arrived by dense similarity, by an exact keyword hit, or because the
         *     cross-encoder rescued it. A `null` field means the stage did not run.
         */
        ScoreBreakdown: {
            /**
             * Age Days
             * @description Chunk age in days, as measured for decay. Null when decay is off.
             */
            age_days?: number | null;
            /**
             * Category
             * @description The chunk's content category, as indexed. Null if it has none.
             */
            category?: string | null;
            /**
             * Category Weight
             * @description The multiplier applied from `category_weights`. Null when the caller sent none; 1.0 when it sent some but had no opinion on this category.
             */
            category_weight?: number | null;
            /**
             * Decay Multiplier
             * @description Temporal decay factor in (0, 1]. Null when decay is off.
             */
            decay_multiplier?: number | null;
            /**
             * Dense Rank
             * @description Best 1-indexed rank this chunk reached in any dense (vector) leg. Null means dense search never returned it — it came from BM25 alone.
             */
            dense_rank?: number | null;
            /**
             * Dense Score
             * @description Cosine similarity to the query in the dense leg (best across query variants). Null when dense search did not return this chunk.
             */
            dense_score?: number | null;
            /**
             * Fused Score
             * @description Score after fusing the search legs — convex (weighted, normalized) by default, RRF if the corpus chose it. Equals `score` unless `category_weights` was sent, in which case `score` is this times `category_weight`.
             */
            fused_score: number;
            /**
             * Pipeline Rank
             * @description 1-indexed position after every ranking stage (rerank, MMR, decay). Note this need NOT match the chunk's position in `chunks`: context assembly re-sorts by `score`, which is the pre-rerank fusion score.
             */
            pipeline_rank: number;
            /**
             * Rerank Score
             * @description Cross-encoder score. Null when reranking is off or it failed.
             */
            rerank_score?: number | null;
            /**
             * Sparse Rank
             * @description 1-indexed rank in the BM25 leg. Null when hybrid search is off for this query, or when BM25 did not return this chunk.
             */
            sparse_rank?: number | null;
            /**
             * Sparse Score
             * @description BM25 score in the keyword leg. Null when that leg did not return it.
             */
            sparse_score?: number | null;
        };
